        { name: 'u', conclusion: 'SUCCESS', completed_at: 'also-garbage', id: 2 }
    ];
    assert.deepEqual(mrReal().failingCheckNames(rollup, null), [],
        'both t=0 — the id tie-break picks the SUCCESS run');
});

